bounded_host_request.command:
set -eu
cid=deploy-gaybbs-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 61
docker exec -i "$cid" node --input-type=module <<'NODE'
import pg from 'pg';
const u=process.env.DATABASE_URL;
if(!u)throw Error('GATE_DATABASE_URL_UNAVAILABLE');
const c=new pg.Client({connectionString:u,connectionTimeoutMillis:5000});
try{
await c.connect();
const t=await c.query("select table_name from information_schema.tables where table_schema='public' and table_name in ('posting_topics','gaybbs_feature_release_gates')");
console.log('OWNER_TABLES='+t.rows.map(r=>r.table_name).join(','));
if(t.rows.some(r=>r.table_name==='posting_topics')){
 const q=await c.query("select topic_id,board_key,purpose,chat_id,message_thread_id,title,enabled,verified_at is not null as has_verification,verified_by is not null as has_verifier from posting_topics where purpose='video_sale' order by topic_id limit 5");
 for(const row of q.rows)console.log('VIDEO_SALE_TOPIC='+JSON.stringify(row));
 console.log('VIDEO_SALE_TOPIC_COUNT='+q.rowCount);
}
if(t.rows.some(r=>r.table_name==='gaybbs_feature_release_gates')){
 const z=await c.query("select feature,enabled,approved_by is not null as has_approval from gaybbs_feature_release_gates where feature='video_sale' limit 5");
 for(const row of z.rows)console.log('RELEASE='+JSON.stringify(row));
}
}finally{await c.end().catch(()=>{})}
NODE
